1	-- CMV (Custo de Mercadoria Vendida) por produto — módulo Financeiro.
2	-- Espelha a semântica de fichas_tecnicas / ficha_tecnica_itens (custo via trigger,
3	-- RLS authenticated sem isolamento por loja). CMV = custo UNITÁRIO da ficha técnica
4	-- (custo_calculado / rendimento_quantidade) + soma dos itens de CMV (embalagem/outros).
5	-- Fonte de verdade do custo: public.compute_item_cost / public.recompute_ficha_cost.
6	-- ADR: .harness/memory-bank/decisions/ADR-20260612-cmv-fichas.md
7	
8	-- ============================================================
9	-- 1. TABELAS
10	-- ============================================================
11	
12	CREATE TABLE IF NOT EXISTS public.cmv_fichas (
13	  id                bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
14	  nome              text        NOT NULL,
15	  ficha_tecnica_id  bigint      NOT NULL UNIQUE
16	                                REFERENCES public.fichas_tecnicas(id) ON DELETE CASCADE,
17	  status            text        NOT NULL DEFAULT 'rascunho',
18	  custo_calculado   numeric     DEFAULT 0,
19	  observacoes       text,
20	  created_by        uuid        REFERENCES auth.users(id),
21	  created_at        timestamptz NOT NULL DEFAULT now(),
22	  updated_at        timestamptz NOT NULL DEFAULT now()
23	);
24	
25	DO $$
26	BEGIN
27	  IF NOT EXISTS (
28	    SELECT 1 FROM pg_constraint
29	    WHERE conname = 'cmv_fichas_status_check'
30	      AND conrelid = 'public.cmv_fichas'::regclass
31	  ) THEN
32	    ALTER TABLE public.cmv_fichas
33	      ADD CONSTRAINT cmv_fichas_status_check
34	      CHECK (status IN ('rascunho', 'aprovada', 'obsoleta'));
35	  END IF;
36	END $$;
37	
38	CREATE TABLE IF NOT EXISTS public.cmv_itens (
39	  id                     bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
40	  cmv_id                 bigint  NOT NULL REFERENCES public.cmv_fichas(id) ON DELETE CASCADE,
41	  tipo                   text    NOT NULL DEFAULT 'embalagem',
42	  insumo_id              bigint  REFERENCES public.insumos(id) ON DELETE SET NULL,
43	  quantidade             numeric NOT NULL DEFAULT 0,
44	  unidade                text    NOT NULL DEFAULT 'un',
45	  preco_unitario_esboco  numeric,
46	  observacao             text,
47	  custo_calculado        numeric DEFAULT 0,
48	  ordem                  integer NOT NULL DEFAULT 0,
49	  created_at             timestamptz NOT NULL DEFAULT now(),
50	  updated_at             timestamptz NOT NULL DEFAULT now()
51	);
52	
53	DO $$
54	BEGIN
55	  IF NOT EXISTS (
56	    SELECT 1 FROM pg_constraint
57	    WHERE conname = 'cmv_itens_tipo_check'
58	      AND conrelid = 'public.cmv_itens'::regclass
59	  ) THEN
60	    ALTER TABLE public.cmv_itens
61	      ADD CONSTRAINT cmv_itens_tipo_check
62	      CHECK (tipo IN ('embalagem', 'outro'));
63	  END IF;
64	END $$;
65	
66	-- Posições do canvas CMV (ReactFlow). Tabela própria — NÃO reusa recipe_canvas_positions.
67	CREATE TABLE IF NOT EXISTS public.cmv_canvas_positions (
68	  cmv_id      bigint      NOT NULL REFERENCES public.cmv_fichas(id) ON DELETE CASCADE,
69	  node_type   text        NOT NULL,
70	  node_id     bigint      NOT NULL,
71	  x           numeric     NOT NULL,
72	  y           numeric     NOT NULL,
73	  updated_at  timestamptz NOT NULL DEFAULT now(),
74	  PRIMARY KEY (cmv_id, node_type, node_id)
75	);
76	
77	DO $$
78	BEGIN
79	  IF NOT EXISTS (
80	    SELECT 1 FROM pg_constraint
81	    WHERE conname = 'cmv_canvas_positions_node_type_check'
82	      AND conrelid = 'public.cmv_canvas_positions'::regclass
83	  ) THEN
84	    ALTER TABLE public.cmv_canvas_positions
85	      ADD CONSTRAINT cmv_canvas_positions_node_type_check
86	      CHECK (node_type IN ('cmv', 'ficha', 'insumo', 'nf', 'item'));
87	  END IF;
88	END $$;
89	
90	-- ============================================================
91	-- 2. ÍNDICES (tabelas vazias — CREATE INDEX simples; CONCURRENTLY não roda em transação)
92	-- ============================================================
93	-- cmv_fichas.ficha_tecnica_id já tem índice via UNIQUE.
94	CREATE INDEX IF NOT EXISTS cmv_itens_cmv_id_idx    ON public.cmv_itens(cmv_id);
95	CREATE INDEX IF NOT EXISTS cmv_itens_insumo_id_idx ON public.cmv_itens(insumo_id);
96	
97	-- ============================================================
98	-- 3. FUNÇÃO DE CUSTO DO ITEM (espelha public.compute_item_cost — mesma conversão de unidade)
99	-- ============================================================
100	CREATE OR REPLACE FUNCTION public.cmv_compute_item_cost(p_item_id bigint)
101	RETURNS numeric
102	LANGUAGE plpgsql
103	SECURITY DEFINER
104	SET search_path TO 'public'
105	AS $function$
106	DECLARE
107	  v_item   RECORD;
108	  v_insumo RECORD;
109	  v_cost   numeric := 0;
110	  v_ratio  numeric := 1.0;
111	  v_uf     text;  -- unidade do item (lower)
112	  v_ui     text;  -- unidade de compra do insumo (lower)
113	BEGIN
114	  SELECT * INTO v_item FROM cmv_itens WHERE id = p_item_id;
115	  IF NOT FOUND THEN RETURN 0; END IF;
116	
117	  -- 1) INSUMO real (preço de compra) com conversão auto entre unidades standard
118	  IF v_item.insumo_id IS NOT NULL THEN
119	    SELECT preco_custo, unidade_compra, fator_conversao
120	      INTO v_insumo
121	      FROM insumos WHERE id = v_item.insumo_id;
122	    IF FOUND AND v_insumo.preco_custo IS NOT NULL THEN
123	      v_uf := lower(coalesce(v_item.unidade, ''));
124	      v_ui := lower(coalesce(v_insumo.unidade_compra, ''));
125	
126	      IF    v_uf = v_ui THEN                       v_ratio := 1.0;
127	      ELSIF v_uf = 'g'  AND v_ui = 'kg' THEN       v_ratio := 0.001;
128	      ELSIF v_uf = 'kg' AND v_ui = 'g'  THEN       v_ratio := 1000;
129	      ELSIF v_uf = 'ml' AND v_ui = 'l'  THEN       v_ratio := 0.001;
130	      ELSIF v_uf = 'l'  AND v_ui = 'ml' THEN       v_ratio := 1000;
131	      ELSIF v_uf = 'mg' AND v_ui = 'g'  THEN       v_ratio := 0.001;
132	      ELSIF v_uf = 'g'  AND v_ui = 'mg' THEN       v_ratio := 1000;
133	      ELSE
134	        -- Unidades não-standard (pack, un, pote, cx): fator_conversao manual
135	        IF v_insumo.fator_conversao IS NOT NULL AND v_insumo.fator_conversao > 0 THEN
136	          v_ratio := 1.0 / v_insumo.fator_conversao;
137	        ELSE
138	          v_ratio := 1.0;
139	        END IF;
140	      END IF;
141	
142	      v_cost := v_insumo.preco_custo * coalesce(v_item.quantidade, 0) * v_ratio;
143	    END IF;
144	  END IF;
145	
146	  -- 2) FALLBACK: esboço (preço livre no item)
147	  IF v_cost = 0 AND v_item.preco_unitario_esboco IS NOT NULL THEN
148	    v_cost := v_item.preco_unitario_esboco * coalesce(v_item.quantidade, 0);
149	  END IF;
150	
151	  RETURN coalesce(v_cost, 0);
152	END;
153	$function$;
154	
155	-- ============================================================
156	-- 4. RECÁLCULO DO TOTAL DA CMV
157	--    custo = custo UNITÁRIO da ficha (custo_calculado / rendimento_quantidade) + Σ itens
158	-- ============================================================
159	CREATE OR REPLACE FUNCTION public.recompute_cmv_cost(p_cmv_id bigint)
160	RETURNS void
161	LANGUAGE plpgsql
162	SECURITY DEFINER
163	SET search_path TO 'public'
164	AS $function$
165	DECLARE
166	  v_item_id        bigint;
167	  v_new_cost       numeric;
168	  v_itens_total    numeric := 0;
169	  v_ficha_unit     numeric := 0;
170	  v_total          numeric := 0;
171	  v_old_total      numeric;
172	  v_ficha_id       bigint;
173	  v_ficha_custo    numeric;
174	  v_ficha_rend     numeric;
175	  v_was_in         text;
176	BEGIN
177	  -- Guard anti-recursão (espelha app.in_recompute das fichas)
178	  v_was_in := current_setting('app.in_cmv_recompute', true);
179	  PERFORM set_config('app.in_cmv_recompute', 'true', true);
180	
181	  -- Recomputar cada item
182	  FOR v_item_id IN SELECT id FROM cmv_itens WHERE cmv_id = p_cmv_id LOOP
183	    v_new_cost := cmv_compute_item_cost(v_item_id);
184	    UPDATE cmv_itens SET custo_calculado = v_new_cost, updated_at = now()
185	     WHERE id = v_item_id;
186	    v_itens_total := v_itens_total + coalesce(v_new_cost, 0);
187	  END LOOP;
188	
189	  -- Custo unitário da ficha técnica atrelada
190	  SELECT cf.ficha_tecnica_id, ft.custo_calculado, ft.rendimento_quantidade
191	    INTO v_ficha_id, v_ficha_custo, v_ficha_rend
192	    FROM cmv_fichas cf
193	    JOIN fichas_tecnicas ft ON ft.id = cf.ficha_tecnica_id
194	   WHERE cf.id = p_cmv_id;
195	
196	  IF v_ficha_id IS NOT NULL AND coalesce(v_ficha_rend, 0) > 0 THEN
197	    v_ficha_unit := coalesce(v_ficha_custo, 0) / v_ficha_rend;
198	  END IF;
199	
200	  v_total := v_ficha_unit + v_itens_total;
201	
202	  SELECT custo_calculado INTO v_old_total FROM cmv_fichas WHERE id = p_cmv_id;
203	  IF v_old_total IS DISTINCT FROM v_total THEN
204	    UPDATE cmv_fichas
205	       SET custo_calculado = v_total, updated_at = now()
206	     WHERE id = p_cmv_id;
207	  END IF;
208	
209	  PERFORM set_config('app.in_cmv_recompute', coalesce(v_was_in, 'false'), true);
210	END;
211	$function$;
212	
213	-- ============================================================
214	-- 5. TRIGGER em cmv_itens — recálculo em INSERT/UPDATE/DELETE
215	-- ============================================================
216	CREATE OR REPLACE FUNCTION public.trg_cmv_item_recompute()
217	RETURNS trigger
218	LANGUAGE plpgsql
219	SECURITY DEFINER
220	SET search_path TO 'public'
221	AS $function$
222	BEGIN
223	  IF current_setting('app.in_cmv_recompute', true) = 'true' THEN
224	    RETURN coalesce(NEW, OLD);
225	  END IF;
226	
227	  IF TG_OP = 'DELETE' THEN
228	    PERFORM recompute_cmv_cost(OLD.cmv_id);
229	    RETURN OLD;
230	  ELSIF TG_OP = 'UPDATE' THEN
231	    IF OLD.cmv_id IS DISTINCT FROM NEW.cmv_id THEN
232	      PERFORM recompute_cmv_cost(OLD.cmv_id);
233	    END IF;
234	    PERFORM recompute_cmv_cost(NEW.cmv_id);
235	    RETURN NEW;
236	  ELSE
237	    PERFORM recompute_cmv_cost(NEW.cmv_id);
238	    RETURN NEW;
239	  END IF;
240	END;
241	$function$;
242	
243	DROP TRIGGER IF EXISTS cmv_item_recompute_trg ON public.cmv_itens;
244	CREATE TRIGGER cmv_item_recompute_trg
245	  AFTER INSERT OR UPDATE OR DELETE ON public.cmv_itens
246	  FOR EACH ROW EXECUTE FUNCTION public.trg_cmv_item_recompute();
247	
248	-- ============================================================
249	-- 6. PROPAGAÇÃO — quando o custo/rendimento da ficha muda, recomputa as CMVs ligadas
250	-- ============================================================
251	CREATE OR REPLACE FUNCTION public.trg_ficha_propagate_cmv()
252	RETURNS trigger
253	LANGUAGE plpgsql
254	SECURITY DEFINER
255	SET search_path TO 'public'
256	AS $function$
257	DECLARE
258	  v_cmv_id bigint;
259	BEGIN
260	  FOR v_cmv_id IN SELECT id FROM cmv_fichas WHERE ficha_tecnica_id = NEW.id LOOP
261	    PERFORM recompute_cmv_cost(v_cmv_id);
262	  END LOOP;
263	  RETURN NEW;
264	END;
265	$function$;
266	
267	DROP TRIGGER IF EXISTS ficha_propagate_cmv_trg ON public.fichas_tecnicas;
268	CREATE TRIGGER ficha_propagate_cmv_trg
269	  AFTER UPDATE OF custo_calculado, rendimento_quantidade ON public.fichas_tecnicas
270	  FOR EACH ROW
271	  WHEN (OLD.custo_calculado IS DISTINCT FROM NEW.custo_calculado
272	        OR OLD.rendimento_quantidade IS DISTINCT FROM NEW.rendimento_quantidade)
273	  EXECUTE FUNCTION public.trg_ficha_propagate_cmv();
274	
275	-- ============================================================
276	-- 7. updated_at em cmv_fichas (BEFORE UPDATE)
277	-- ============================================================
278	CREATE OR REPLACE FUNCTION public.set_cmv_fichas_updated_at()
279	RETURNS trigger
280	LANGUAGE plpgsql
281	SET search_path TO 'public'
282	AS $function$
283	BEGIN
284	  NEW.updated_at := now();
285	  RETURN NEW;
286	END;
287	$function$;
288	
289	DROP TRIGGER IF EXISTS trg_cmv_fichas_updated_at ON public.cmv_fichas;
290	CREATE TRIGGER trg_cmv_fichas_updated_at
291	  BEFORE UPDATE ON public.cmv_fichas
292	  FOR EACH ROW EXECUTE FUNCTION public.set_cmv_fichas_updated_at();
293	
294	-- ============================================================
295	-- 8. RLS — espelho EXATO de fichas_tecnicas: ALL TO authenticated USING(true) WITH CHECK(true)
296	--    Sem policy anon. Tabelas da fábrica/rede — sem loja_id / sem isolamento por loja.
297	-- ============================================================
298	ALTER TABLE public.cmv_fichas           ENABLE ROW LEVEL SECURITY;
299	ALTER TABLE public.cmv_itens            ENABLE ROW LEVEL SECURITY;
300	ALTER TABLE public.cmv_canvas_positions ENABLE ROW LEVEL SECURITY;
301	
302	DO $$
303	BEGIN
304	  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname='public' AND tablename='cmv_fichas' AND policyname='auth_all_cmv_fichas') THEN
305	    CREATE POLICY auth_all_cmv_fichas ON public.cmv_fichas
306	      FOR ALL TO authenticated USING (true) WITH CHECK (true);
307	  END IF;
308	
309	  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname='public' AND tablename='cmv_itens' AND policyname='auth_all_cmv_itens') THEN
310	    CREATE POLICY auth_all_cmv_itens ON public.cmv_itens
311	      FOR ALL TO authenticated USING (true) WITH CHECK (true);
312	  END IF;
313	
314	  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname='public' AND tablename='cmv_canvas_positions' AND policyname='auth_all_cmv_canvas') THEN
315	    CREATE POLICY auth_all_cmv_canvas ON public.cmv_canvas_positions
316	      FOR ALL TO authenticated USING (true) WITH CHECK (true);
317	  END IF;
318	END $$;
319	
320	-- ============================================================
321	-- DOWN (referência):
322	--   DROP TRIGGER IF EXISTS ficha_propagate_cmv_trg ON public.fichas_tecnicas;
323	--   DROP FUNCTION IF EXISTS public.trg_ficha_propagate_cmv();
324	--   DROP TABLE IF EXISTS public.cmv_canvas_positions;
325	--   DROP TABLE IF EXISTS public.cmv_itens;       -- trigger cai junto
326	--   DROP TABLE IF EXISTS public.cmv_fichas;
327	--   DROP FUNCTION IF EXISTS public.trg_cmv_item_recompute();
328	--   DROP FUNCTION IF EXISTS public.recompute_cmv_cost(bigint);
329	--   DROP FUNCTION IF EXISTS public.cmv_compute_item_cost(bigint);
330	--   DROP FUNCTION IF EXISTS public.set_cmv_fichas_updated_at();
331	-- ============================================================
