476	  const handleDeleteItem = useCallback(async () => {
477	    if (!selectedItemData) return;
478	    setIsDeleting(true);
479	    const { error } = await supabase
480	      .from('cmv_itens')
481	      .delete()
482	      .eq('id', selectedItemData.id);
483	
484	    if (error) {
485	      toast.error(`Erro ao excluir: ${error.message}`);
486	    } else {
487	      toast.success('Item removido!');
488	      setSelectedItemData(null);
489	      await refetch();
490	      queryClient.invalidateQueries({ queryKey: ['cmv_fichas'] });
491	    }
492	    setIsDeleting(false);
493	  }, [selectedItemData, refetch, queryClient]);
494	
495	  // -------------------------------------------------------------------------
496	  // Add item
497	  // -------------------------------------------------------------------------
498	  const handleAddItem = useCallback(async () => {
499	    if (!cmvId) return;
