1	import { supabase } from '@/integrations/supabase/client';
2	import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
3	import { toast } from 'sonner';
4	
5	export type CmvStatus = 'rascunho' | 'aprovada' | 'obsoleta';
6	
7	export interface CmvFicha {
8	  id: number;
9	  nome: string;
10	  ficha_tecnica_id: number;
11	  status: CmvStatus;
12	  custo_calculado: number | null;
13	  observacoes: string | null;
14	  created_at: string;
15	  updated_at: string;
16	  ficha_nome?: string;
17	  ficha_custo_calculado?: number;
18	  ficha_rendimento_quantidade?: number;
19	  ficha_rendimento_unidade?: string;
20	}
21	
22	export interface FichaDisponivel {
23	  id: number;
24	  nome: string;
25	  custo_calculado: number;
26	  rendimento_quantidade: number;
27	  rendimento_unidade: string;
28	}
29	
30	export function useCmvFichas() {
31	  const queryClient = useQueryClient();
32	
33	  const cmvListQuery = useQuery({
34	    queryKey: ['cmv_fichas'],
35	    queryFn: async (): Promise<CmvFicha[]> => {
36	      const { data, error } = await supabase
37	        .from('cmv_fichas')
38	        .select(`
39	          *,
40	          fichas_tecnicas (
41	            nome,
42	            custo_calculado,
43	            rendimento_quantidade,
44	            rendimento_unidade
45	          )
46	        `);
47	
48	      if (error) {
49	        throw new Error(error.message);
50	      }
51	
52	      type SupabaseResponse = Omit<CmvFicha, 'ficha_nome' | 'ficha_custo_calculado' | 'ficha_rendimento_quantidade' | 'ficha_rendimento_unidade'> & {
53	        fichas_tecnicas: {
54	          nome: string;
55	          custo_calculado: number;
56	          rendimento_quantidade: number;
57	          rendimento_unidade: string;
58	        } | null | undefined;
59	      };
60	
61	      return (data as unknown as SupabaseResponse[] || []).map((item) => ({
62	        id: item.id,
63	        nome: item.nome,
64	        ficha_tecnica_id: item.ficha_tecnica_id,
65	        status: item.status,
66	        custo_calculado: item.custo_calculado,
67	        observacoes: item.observacoes,
68	        created_at: item.created_at,
69	        updated_at: item.updated_at,
70	        ficha_nome: item.fichas_tecnicas?.nome,
71	        ficha_custo_calculado: item.fichas_tecnicas?.custo_calculado,
72	        ficha_rendimento_quantidade: item.fichas_tecnicas?.rendimento_quantidade,
73	        ficha_rendimento_unidade: item.fichas_tecnicas?.rendimento_unidade,
74	      }));
75	    },
76	  });
77	
78	  const availableFichasQuery = useQuery({
79	    queryKey: ['fichas_aprovadas_sem_cmv'],
80	    queryFn: async (): Promise<FichaDisponivel[]> => {
81	      const [fichasRes, cmvRes] = await Promise.all([
82	        supabase
83	          .from('fichas_tecnicas')
84	          .select('id, nome, custo_calculado, rendimento_quantidade, rendimento_unidade')
85	          .eq('status', 'aprovada'),
86	        supabase
87	          .from('cmv_fichas')
88	          .select('ficha_tecnica_id'),
89	      ]);
90	
91	      if (fichasRes.error) {
92	        throw new Error(fichasRes.error.message);
93	      }
94	      if (cmvRes.error) {
95	        throw new Error(cmvRes.error.message);
96	      }
97	
98	      const cmvFichasIds = new Set(cmvRes.data?.map((cmv) => cmv.ficha_tecnica_id) ?? []);
99	
100	      return (fichasRes.data as unknown as FichaDisponivel[] || []).filter(
101	        (ficha) => !cmvFichasIds.has(ficha.id),
102	      );
103	    },
104	  });
105	
106	  const createCmv = useMutation({
107	    mutationFn: async ({ ficha_tecnica_id, nome }: { ficha_tecnica_id: number; nome: string }) => {
108	      const { data, error } = await supabase
109	        .from('cmv_fichas')
110	        .insert({ ficha_tecnica_id, nome, status: 'rascunho' as CmvStatus })
111	        .select()
112	        .single();
113	
114	      if (error) {
115	        throw new Error(error.message);
116	      }
117	      return data;
118	    },
119	    onSuccess: () => {
120	      queryClient.invalidateQueries({ queryKey: ['cmv_fichas'] });
121	      queryClient.invalidateQueries({ queryKey: ['fichas_aprovadas_sem_cmv'] });
122	      toast.success('CMV criado com sucesso!');
123	    },
124	    onError: (error: Error) => {
125	      toast.error(`Erro ao criar CMV: ${error.message}`);
126	    },
127	  });
128	
129	  const updateCmvStatus = useMutation({
130	    mutationFn: async ({ id, status }: { id: number; status: CmvStatus }) => {
131	      const { data, error } = await supabase
132	        .from('cmv_fichas')
133	        .update({ status })
134	        .eq('id', id)
135	        .select()
136	        .single();
137	
138	      if (error) {
139	        throw new Error(error.message);
140	      }
141	      return data;
142	    },
143	    onSuccess: () => {
144	      queryClient.invalidateQueries({ queryKey: ['cmv_fichas'] });
145	      toast.success('Status do CMV atualizado com sucesso!');
146	    },
147	    onError: (error: Error) => {
148	      toast.error(`Erro ao atualizar status: ${error.message}`);
149	    },
150	  });
151	
152	  const deleteCmv = useMutation({
153	    mutationFn: async (id: number) => {
154	      const { error } = await supabase
155	        .from('cmv_fichas')
156	        .delete()
157	        .eq('id', id);
158	
159	      if (error) {
160	        throw new Error(error.message);
161	      }
162	    },
163	    onSuccess: () => {
164	      queryClient.invalidateQueries({ queryKey: ['cmv_fichas'] });
165	      queryClient.invalidateQueries({ queryKey: ['fichas_aprovadas_sem_cmv'] });
166	      toast.success('CMV excluído com sucesso!');
167	    },
168	    onError: (error: Error) => {
169	      toast.error(`Erro ao excluir CMV: ${error.message}`);
170	    },
171	  });
172	
173	  return {
174	    cmvList: cmvListQuery.data ?? [],
175	    availableFichas: availableFichasQuery.data ?? [],
176	    isLoading: cmvListQuery.isLoading || availableFichasQuery.isLoading,
177	    createCmv,
178	    updateCmvStatus,
179	    deleteCmv,
180	  };
181	}
